// Generated by lib/generate-noun.ts from qsm.json. Do not hand-edit; run
// `bun lib/generate-noun.ts plugins/<name>` again after changing qsm.json.

export type Index = {
  build(options: {
    path: string;
  }): Promise<unknown>;
  search(options: {
    path: string;
    query: string;
    top_k?: number;
  }): Promise<unknown>;
  structure(options: {
    repo: string;
    op: "explain" | "path";
    node: string;
    to?: string;
  }): Promise<unknown>;
  impact(options: {
    repo: string;
    node: string;
    depth?: number;
  }): Promise<unknown>;
  context(options: {
    repo: string;
    target: string;
  }): Promise<unknown>;
  reindex(options: {
    path: string;
    ifIndexed?: boolean;
  }): Promise<unknown>;
  edited(options: {
    path: string;
    cwd?: string;
  }): Promise<unknown>;
  status(options: {
    path: string;
  }): Promise<unknown>;
  auto(options: {
    path: string;
    consent?: "yes" | "no";
  }): Promise<unknown>;
  doctor(): Promise<unknown>;
};

declare module 'claude-code' {
  interface EngineInterface {
    index: Index;
  }
}
